/* @lc app=leetcode id=2916 lang=kotlin */ class Solution { fun ap(s: LongArray, q: LongArray, z: LongArray, o: Int, len: Int, v: Long) = q.set(o, (q[o] + 2 * v % 1_000_000_007L * s[o] + len.toLong() * v % 1_000_000_007L * v) % 1_000_000_007L).also { s[o] = (s[o] + len * v) % 1_000_000_007L }.also { z[o] = (z[o] + v) % 1_000_000_007L } fun upd(s: LongArray, q: LongArray, z: LongArray, o: Int, l: Int, r: Int, a: Int, b: Int): Unit = if (a <= l && r <= b) ap(s, q, z, o, r - l + 1, 1L) else ((l + r) / 2).let { m -> (if (z[o] != 0L) ap(s, q, z, 2 * o, m - l + 1, z[o]).also { ap(s, q, z, 2 * o + 1, r - m, z[o]) }.also { z[o] = 0L } else Unit).also { if (a <= m) upd(s, q, z, 2 * o, l, m, a, b) }.also { if (b > m) upd(s, q, z, 2 * o + 1, m + 1, r, a, b) }.also { s[o] = (s[2 * o] + s[2 * o + 1]) % 1_000_000_007L }.also { q[o] = (q[2 * o] + q[2 * o + 1]) % 1_000_000_007L } } fun sumCounts(nums: IntArray): Int = nums.size.let { n -> LongArray(4 * n).let { s -> LongArray(4 * n).let { q -> LongArray(4 * n).let { z -> HashMap<Int, Int>().let { last -> nums.indices.fold(0L) { tot, r -> upd(s, q, z, 1, 0, n - 1, (last[nums[r]] ?: -1) + 1, r).let { last[nums[r]] = r }.let { (tot + q[1]) % 1_000_000_007L } }.toInt() } } } } } }